WITH post AS (SELECT * FROM "posts" ORDER BY "created_at" DESC, "id" ASC LIMIT 10) SELECT "author"."address" AS "author.address", "author"."birthday" AS "author.birthday", "author"."created_at" AS "author.created_at", "author"."email" AS "author.email", "author"."email_verified" AS "author.email_verified", "author"."first_name" AS "author.first_name", "author"."gender" AS "author.gender", "author"."id" AS "author.id", "author"."last_name" AS "author.last_name", "author"."updated_at" AS "author.updated_at", "comment"."content" AS "comment.content", "comment"."created_at" AS "comment.created_at", "comment"."id" AS "comment.id", "comment"."parent_id" AS "comment.parent_id", "comment"."post_id" AS "comment.post_id", "comment"."updated_at" AS "comment.updated_at", "comment"."user_id" AS "comment.user_id", "post"."content" AS "post.content", "post"."created_at" AS "post.created_at", "post"."id" AS "post.id", "post"."title" AS "post.title", "post"."updated_at" AS "post.updated_at", "post"."user_id" AS "post.user_id", "reaction"."comment_id" AS "reaction.comment_id", "reaction"."created_at" AS "reaction.created_at", "reaction"."emoji" AS "reaction.emoji", "reaction"."id" AS "reaction.id", "reaction"."user_id" AS "reaction.user_id" FROM "post" INNER JOIN "users" AS "author" ON ("author"."id" = "post"."user_id") LEFT JOIN "comments" AS "comment" ON ("comment"."post_id" = "post"."id") LEFT JOIN "reactions" AS "reaction" ON ("reaction"."comment_id" = "comment"."id") ORDER BY "post"."created_at" DESC, "post"."id" ASC, "comment"."created_at" ASC, "comment"."id" ASC, "reaction"."created_at" ASC, "reaction"."id" ASC;
